('847', '481', '55', '1. มีความซื่อสัตย์ สุจริต รักษาประโยชน์ส่วนรวม ไม่อาศัยหรือยินยอมให้ผู้อื่นใช้อำนาจและหน้าที่ของตนเพื่อแสวงหาประโยชน์\r\n           *ข้าพเจ้าได้ปฏิบัติงานด้วยความซื่อสัตย์สุจริต  เที่ยงตรงและเที่ยงธรรม  ได้รับการยอมรับจากเพื่อนร่วมงานและผู้บังคับบัญชา ในงานที่เกี่ยวกับบทบาทหน้าที่  และภารกิจ   ที่ตนรับผิดชอบ', NULL, 'https://sites.google.com/view/aumpika2568/%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%A3%E0%B8%81%E0%B8%A9%E0%B8%B2%E0%B8%A7%E0%B8%99%E0%B8%A2-%E0%B8%84%E0%B8%93%E0%B8%98%E0%B8%A3%E0%B8%A3%E0%B8%A1-%E0%B8%88%E0%B8%A3%E0%B8%A2%E0%B8%98%E0%B8%A3%E0%B8%A3%E0%B8%A1-%E0%B9%81%E0%B8%A5%E0%B8%B0%E0%B8%88%E0%B8%A3%E0%B8%A3%E0%B8%A2%E0%B8%B2%E0%B8%9A%E0%B8%A3%E0%B8%A3%E0%B8%93%E0%B8%A7%E0%B8%8A%E0%B8%B2%E0%B8%8A%E0%B8%9E?authuser=0'),
