('855', '481', '57', '3. ความวิริยะ อุตสาหะ ตรงต่อเวลา และ อุทิศเวลาให้แก่ทางราชการ\r\n     *ดังนี้  มีความพร้อมในการปฏิบัติงานตามบทบาทหน้าที่  ภารกิจที่ได้รับมอบหมาย  และอุทิศเวลาโดยมีจิตสำนึกและ ความรับผิดชอบ', NULL, 'https://sites.google.com/view/aumpika2568/%E0%B8%81%E0%B8%B2%E0%B8%A3%E0%B8%A3%E0%B8%81%E0%B8%A9%E0%B8%B2%E0%B8%A7%E0%B8%99%E0%B8%A2-%E0%B8%84%E0%B8%93%E0%B8%98%E0%B8%A3%E0%B8%A3%E0%B8%A1-%E0%B8%88%E0%B8%A3%E0%B8%A2%E0%B8%98%E0%B8%A3%E0%B8%A3%E0%B8%A1-%E0%B9%81%E0%B8%A5%E0%B8%B0%E0%B8%88%E0%B8%A3%E0%B8%A3%E0%B8%A2%E0%B8%B2%E0%B8%9A%E0%B8%A3%E0%B8%A3%E0%B8%93%E0%B8%A7%E0%B8%8A%E0%B8%B2%E0%B8%8A%E0%B8%9E?authuser=0'),
