('1266', '505', '26', 'ปฏิบัติงานตามภารกิจด้านการพัฒนาหลักสูตรการเรียนการสอน และการดำเนินงานอาชีวศึกษาระบบทวิภาคี โดยสามารถดำเนินการพัฒนาหลักสูตร ปรับปรุงแผนการจัดการเรียนรู้ ตลอดจนประสานงานสถานประกอบการและจัดการเรียนการสอนในระบบทวิภาคี  แล้วเสร็จภายในระยะเวลาที่กำหนด คิดเป็นร้อยละ 100 ของแผนการดำเนินงาน', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1usI5KWwsJ7wLCoPL2CexMOi3EnHH-lMx/edit?pli=1'),
('1267', '506', '26', 'ปฏิบัติงานตามภารกิจด้านการพัฒนาหลักสูตรการเรียนการสอน และการดำเนินงานอาชีวศึกษาระบบทวิภาคี โดยสามารถดำเนินการพัฒนาหลักสูตร ปรับปรุงแผนการจัดการเรียนรู้ ตลอดจนประสานงานสถานประกอบการและจัดการเรียนการสอนในระบบทวิภาคี  แล้วเสร็จภายในระยะเวลาที่กำหนด คิดเป็นร้อยละ 100 ของแผนการดำเนินงาน', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1usI5KWwsJ7wLCoPL2CexMOi3EnHH-lMx/edit?pli=1'),
('1268', '505', '28', 'การปฏิบัติงานด้านการพัฒนาหลักสูตรการเรียนการสอน และการดำเนินงานอาชีวศึกษาระบบทวิภาคี เป็นไปด้วยความถูกต้องตามหลักเกณฑ์ มาตรฐาน และระเบียบที่เกี่ยวข้อง มีความประณีตเรียบร้อย ครบถ้วนตามรูปแบบทางราชการ สามารถตรวจสอบได้', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/18V4PlcoUGMLuD9J1FIuA0T4n4cS2YZlm/edit?pli=1'),
('1269', '506', '28', 'การปฏิบัติงานด้านการพัฒนาหลักสูตรการเรียนการสอน และการดำเนินงานอาชีวศึกษาระบบทวิภาคี เป็นไปด้วยความถูกต้องตามหลักเกณฑ์ มาตรฐาน และระเบียบที่เกี่ยวข้อง มีความประณีตเรียบร้อย ครบถ้วนตามรูปแบบทางราชการ สามารถตรวจสอบได้', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/18V4PlcoUGMLuD9J1FIuA0T4n4cS2YZlm/edit?pli=1'),
('1270', '505', '31', 'ผลการดำเนินงานทั้งสองด้านเป็นไปตามเป้าหมายและวัตถุประสงค์ที่กำหนดไว้ สะท้อนถึงประสิทธิภาพและความสำเร็จของการดำเนินงานในภาพรวม', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/17ziq1sPb_2epWmdJugSeYABQnQ-EOAZ7/edit?pli=1'),
('1271', '506', '31', 'ผลการดำเนินงานทั้งสองด้านเป็นไปตามเป้าหมายและวัตถุประสงค์ที่กำหนดไว้ สะท้อนถึงประสิทธิภาพและความสำเร็จของการดำเนินงานในภาพรวม', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/17ziq1sPb_2epWmdJugSeYABQnQ-EOAZ7/edit?pli=1'),
('1272', '505', '33', 'สามารถปฏิบัติงานตามหน้าที่ด้านการพัฒนาหลักสูตรการเรียนการสอน และการดำเนินงานอาชีวศึกษาระบบทวิภาคีได้แล้วเสร็จภายในระยะเวลาที่กำหนด เป็นไปตามแผนการดำเนินงานและปฏิทินที่วางไว้', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1z_AdzVmQ_gWUOAnxnNSKonehDa-l1Rzv/edit?pli=1'),
('1273', '506', '33', 'สามารถปฏิบัติงานตามหน้าที่ด้านการพัฒนาหลักสูตรการเรียนการสอน และการดำเนินงานอาชีวศึกษาระบบทวิภาคีได้แล้วเสร็จภายในระยะเวลาที่กำหนด เป็นไปตามแผนการดำเนินงานและปฏิทินที่วางไว้', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1z_AdzVmQ_gWUOAnxnNSKonehDa-l1Rzv/edit?pli=1'),
('1274', '505', '27', 'ได้รับมอบหมายให้ดำเนินการจัดทำเอกสารหลักสูตร คู่มือการจัดการเรียนการสอน และรายงานผลการดำเนินงาน  โดยสามารถดำเนินการแล้วเสร็จครบถ้วนตามเป้าหมายที่กำหนดทุกประการ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1usI5KWwsJ7wLCoPL2CexMOi3EnHH-lMx/edit?pli=1'),
('1275', '506', '27', 'ได้รับมอบหมายให้ดำเนินการจัดทำเอกสารหลักสูตร คู่มือการจัดการเรียนการสอน และรายงานผลการดำเนินงาน  โดยสามารถดำเนินการแล้วเสร็จครบถ้วนตามเป้าหมายที่กำหนดทุกประการ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1usI5KWwsJ7wLCoPL2CexMOi3EnHH-lMx/edit?pli=1'),
('1276', '505', '29', 'ผลงานที่ดำเนินการมีความสมบูรณ์ ครบถ้วนตามองค์ประกอบของหลักสูตร เอกสารประกอบการเรียนการสอน และเอกสารที่เกี่ยวข้องกับระบบทวิภาคี ครอบคลุมตามภารกิจที่ได้รับมอบหมายทุกประการ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/18V4PlcoUGMLuD9J1FIuA0T4n4cS2YZlm/edit?pli=1'),
('1277', '506', '29', 'ผลงานที่ดำเนินการมีความสมบูรณ์ ครบถ้วนตามองค์ประกอบของหลักสูตร เอกสารประกอบการเรียนการสอน และเอกสารที่เกี่ยวข้องกับระบบทวิภาคี ครอบคลุมตามภารกิจที่ได้รับมอบหมายทุกประการ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/18V4PlcoUGMLuD9J1FIuA0T4n4cS2YZlm/edit?pli=1'),
('1278', '505', '32', 'ผลงานของทั้งสองงานสามารถนำไปใช้ประโยชน์ได้อย่างเป็นรูปธรรม ทั้งในด้านการจัดการศึกษา การพัฒนาผู้เรียน และการตอบสนองต่อความต้องการของภาคส่วนที่เกี่ยวข้อง', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/17ziq1sPb_2epWmdJugSeYABQnQ-EOAZ7/edit?pli=1'),
('1279', '506', '32', 'ผลงานของทั้งสองงานสามารถนำไปใช้ประโยชน์ได้อย่างเป็นรูปธรรม ทั้งในด้านการจัดการศึกษา การพัฒนาผู้เรียน และการตอบสนองต่อความต้องการของภาคส่วนที่เกี่ยวข้อง', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/17ziq1sPb_2epWmdJugSeYABQnQ-EOAZ7/edit?pli=1'),
('1280', '505', '34', 'การปฏิบัติงานตามที่ได้รับมอบหมายเป็นไปด้วยความเรียบร้อย สามารถดำเนินการแล้วเสร็จทันตามระยะเวลาที่กำหนดทุกภารกิจ ไม่ส่งผลกระทบต่อการดำเนินงานในส่วนที่เกี่ยวข้อง', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1z_AdzVmQ_gWUOAnxnNSKonehDa-l1Rzv/edit?pli=1'),
('1281', '506', '34', 'การปฏิบัติงานตามที่ได้รับมอบหมายเป็นไปด้วยความเรียบร้อย สามารถดำเนินการแล้วเสร็จทันตามระยะเวลาที่กำหนดทุกภารกิจ ไม่ส่งผลกระทบต่อการดำเนินงานในส่วนที่เกี่ยวข้อง', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1z_AdzVmQ_gWUOAnxnNSKonehDa-l1Rzv/edit?pli=1'),
('1282', '505', '30', 'การดำเนินงานบรรลุตามวัตถุประสงค์และเป้าหมายที่กำหนด โดยไม่พบข้อผิดพลาดที่ส่งผลกระทบต่อการดำเนินงานในภาพรวม และไม่ก่อให้เกิดปัญหาตามมาภายหลัง สามารถนำไปใช้ประโยชน์ได้อย่างมีประสิทธิภาพ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/18V4PlcoUGMLuD9J1FIuA0T4n4cS2YZlm/edit?pli=1'),
('1283', '506', '30', 'การดำเนินงานบรรลุตามวัตถุประสงค์และเป้าหมายที่กำหนด โดยไม่พบข้อผิดพลาดที่ส่งผลกระทบต่อการดำเนินงานในภาพรวม และไม่ก่อให้เกิดปัญหาตามมาภายหลัง สามารถนำไปใช้ประโยชน์ได้อย่างมีประสิทธิภาพ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/18V4PlcoUGMLuD9J1FIuA0T4n4cS2YZlm/edit?pli=1'),
('1284', '505', '21', 'จากการปฏิบัติงานด้านการพัฒนาหลักสูตรการเรียนการสอน และงานอาชีวศึกษาระบบทวิภาคี รวมถึงงานอื่น ๆ ที่ได้รับมอบหมาย สามารถดำเนินงานได้บรรลุตามเป้าหมายทั้งด้านปริมาณ คุณภาพ และระยะเวลา โดยผลงานมีความถูกต้อง ครบถ้วน เป็นไปตามหลักเกณฑ์และระเบียบที่เกี่ยวข้อง และแล้วเสร็จภายในระยะเวลาที่กำหนดทุกภารกิจ\r\n\r\nทั้งนี้ การดำเนินงานไม่พบข้อผิดพลาดที่ส่งผลกระทบในภาพรวม และไม่ก่อให้เกิดปัญหาตามมาในภายหลัง สามารถสนับสนุนการดำเนินงานของหน่วยงานให้เป็นไปอย่างมีประสิทธิภาพและบรรลุวัตถุประสงค์ที่กำหนดไว้ทุกประการ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1sLZhnG2gSJ_5_9-fGZYMVsBqjZAQKYut/edit?pli=1'),
('1285', '506', '21', 'จากการปฏิบัติงานด้านการพัฒนาหลักสูตรการเรียนการสอน และงานอาชีวศึกษาระบบทวิภาคี รวมถึงงานอื่น ๆ ที่ได้รับมอบหมาย สามารถดำเนินงานได้บรรลุตามเป้าหมายทั้งด้านปริมาณ คุณภาพ และระยะเวลา โดยผลงานมีความถูกต้อง ครบถ้วน เป็นไปตามหลักเกณฑ์และระเบียบที่เกี่ยวข้อง และแล้วเสร็จภายในระยะเวลาที่กำหนดทุกภารกิจ\r\n\r\nทั้งนี้ การดำเนินงานไม่พบข้อผิดพลาดที่ส่งผลกระทบในภาพรวม และไม่ก่อให้เกิดปัญหาตามมาในภายหลัง สามารถสนับสนุนการดำเนินงานของหน่วยงานให้เป็นไปอย่างมีประสิทธิภาพและบรรลุวัตถุประสงค์ที่กำหนดไว้ทุกประการ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1sLZhnG2gSJ_5_9-fGZYMVsBqjZAQKYut/edit?pli=1'),
('1286', '505', '22', 'เข้าร่วมกิจกรรมต่าง ๆ ทั้งภายในและภายนอกสถานศึกษาอย่างสม่ำเสมอ อาทิ การประชุม อบรม สัมมนา และกิจกรรมพัฒนาวิชาชีพ โดยให้ความร่วมมือในการดำเนินงานเป็นอย่างดี มีความรับผิดชอบ และปฏิบัติตามระเบียบที่เกี่ยวข้องอย่างเคร่งครัด\r\n\r\nสามารถนำความรู้และประสบการณ์ที่ได้รับจากการเข้าร่วมกิจกรรมมาประยุกต์ใช้ในการพัฒนาการจัดการเรียนการสอน และการปฏิบัติงานในหน้าที่ได้อย่างมีประสิทธิภาพ ส่งผลให้เกิดประโยชน์ต่อผู้เรียนและหน่วยงานโดยรวม', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1_9kYEWAkNIlFT_ejNQbbT01I1dX9lhHt/edit?pli=1'),
('1287', '506', '22', 'เข้าร่วมกิจกรรมต่าง ๆ ทั้งภายในและภายนอกสถานศึกษาอย่างสม่ำเสมอ อาทิ การประชุม อบรม สัมมนา และกิจกรรมพัฒนาวิชาชีพ โดยให้ความร่วมมือในการดำเนินงานเป็นอย่างดี มีความรับผิดชอบ และปฏิบัติตามระเบียบที่เกี่ยวข้องอย่างเคร่งครัด\r\n\r\nสามารถนำความรู้และประสบการณ์ที่ได้รับจากการเข้าร่วมกิจกรรมมาประยุกต์ใช้ในการพัฒนาการจัดการเรียนการสอน และการปฏิบัติงานในหน้าที่ได้อย่างมีประสิทธิภาพ ส่งผลให้เกิดประโยชน์ต่อผู้เรียนและหน่วยงานโดยรวม', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1_9kYEWAkNIlFT_ejNQbbT01I1dX9lhHt/edit?pli=1'),
('1288', '505', '23', 'ปฏิบัติตามกฎ ระเบียบ ข้อบังคับ นโยบาย และคำสั่งของผู้บังคับบัญชาอย่างเคร่งครัด โดยยึดถือหลักความถูกต้อง โปร่งใส และเป็นธรรมในการปฏิบัติงาน\r\n\r\nมีความรับผิดชอบต่อหน้าที่ ปฏิบัติงานด้วยความรอบคอบ และคำนึงถึงประโยชน์ของทางราชการเป็นสำคัญ พร้อมทั้งให้ความร่วมมือในการขับเคลื่อนนโยบายและแนวทางการดำเนินงานของหน่วยงานให้เป็นไปตามเป้าหมายที่กำหนดอย่างมีประสิทธิภาพ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1gGeI5edRrsKNFCQmjaytnuvsh19RjC58/edit?pli=1'),
('1289', '506', '23', 'ปฏิบัติตามกฎ ระเบียบ ข้อบังคับ นโยบาย และคำสั่งของผู้บังคับบัญชาอย่างเคร่งครัด โดยยึดถือหลักความถูกต้อง โปร่งใส และเป็นธรรมในการปฏิบัติงาน\r\n\r\nมีความรับผิดชอบต่อหน้าที่ ปฏิบัติงานด้วยความรอบคอบ และคำนึงถึงประโยชน์ของทางราชการเป็นสำคัญ พร้อมทั้งให้ความร่วมมือในการขับเคลื่อนนโยบายและแนวทางการดำเนินงานของหน่วยงานให้เป็นไปตามเป้าหมายที่กำหนดอย่างมีประสิทธิภาพ', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1gGeI5edRrsKNFCQmjaytnuvsh19RjC58/edit?pli=1'),
('1290', '505', '24', 'มีความเสียสละและอุทิศเวลาในการปฏิบัติงานให้แก่ทางราชการอย่างเต็มความสามารถ โดยคำนึงถึงประโยชน์ของหน่วยงานเป็นสำคัญ สามารถปฏิบัติงานนอกเวลาราชการหรือในวันหยุดราชการได้ตามความจำเป็น เพื่อให้ภารกิจของหน่วยงานดำเนินไปอย่างต่อเนื่องและบรรลุผลสำเร็จ\r\nปฏิบัติงานด้วยความมุ่งมั่น ตั้งใจ และมีความรับผิดชอบสูง พร้อมให้ความร่วมมือในการสนับสนุนภารกิจต่าง ๆ ของหน่วยงานอย่างเต็มที่ ส่งผลให้การดำเนินงานเป็นไปอย่างมีประสิทธิภาพและเกิดประโยชน์สูงสุด', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1mbOvN-ulXSb5Kna9dOZKq9hxXHZvJvia/edit?pli=1'),
('1291', '506', '24', 'มีความเสียสละและอุทิศเวลาในการปฏิบัติงานให้แก่ทางราชการอย่างเต็มความสามารถ โดยคำนึงถึงประโยชน์ของหน่วยงานเป็นสำคัญ สามารถปฏิบัติงานนอกเวลาราชการหรือในวันหยุดราชการได้ตามความจำเป็น เพื่อให้ภารกิจของหน่วยงานดำเนินไปอย่างต่อเนื่องและบรรลุผลสำเร็จ\r\nปฏิบัติงานด้วยความมุ่งมั่น ตั้งใจ และมีความรับผิดชอบสูง พร้อมให้ความร่วมมือในการสนับสนุนภารกิจต่าง ๆ ของหน่วยงานอย่างเต็มที่ ส่งผลให้การดำเนินงานเป็นไปอย่างมีประสิทธิภาพและเกิดประโยชน์สูงสุด', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1mbOvN-ulXSb5Kna9dOZKq9hxXHZvJvia/edit?pli=1'),
('1292', '505', '25', 'การลา\r\nมีการลาป่วย จำนวน 2 วัน โดยได้ดำเนินการตามระเบียบของทางราชการอย่างถูกต้อง และไม่ส่งผลกระทบต่อการปฏิบัติงานในหน้าที่\r\nการมาปฏิบัติงาน\r\nมาปฏิบัติงานอย่างสม่ำเสมอ ตรงต่อเวลา ไม่ปรากฏการมาสายหรือขาดงานโดยไม่มีเหตุอันสมควร', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1AOGJMStpYaWdDSXYy9P2bfGonVSxitUL/edit?pli=1'),
('1293', '506', '25', 'การลา\r\nมีการลาป่วย จำนวน 2 วัน โดยได้ดำเนินการตามระเบียบของทางราชการอย่างถูกต้อง และไม่ส่งผลกระทบต่อการปฏิบัติงานในหน้าที่\r\nการมาปฏิบัติงาน\r\nมาปฏิบัติงานอย่างสม่ำเสมอ ตรงต่อเวลา ไม่ปรากฏการมาสายหรือขาดงานโดยไม่มีเหตุอันสมควร', NULL, 'https://sites.google.com/d/1HTmv-pridN0P8By2aIj1JXz1ofd_r0Nc/p/1AOGJMStpYaWdDSXYy9P2bfGonVSxitUL/edit?pli=1'),
