-- 
-- Table structure for table `evaluation_evaluator_scores`
-- 

DROP TABLE IF EXISTS `evaluation_evaluator_scores`;
CREATE TABLE `evaluation_evaluator_scores` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `evaluation_evaluator_status_id` int(11) NOT NULL,
  `criteria_id` int(11) NOT NULL,
  `score` decimal(5,2) NOT NULL DEFAULT 0.00,
  `comment` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ev_score` (`evaluation_evaluator_status_id`,`criteria_id`),
  KEY `criteria_id` (`criteria_id`),
  CONSTRAINT `evaluation_evaluator_scores_ibfk_1` FOREIGN KEY (`evaluation_evaluator_status_id`) REFERENCES `evaluation_evaluator_status` (`id`) ON DELETE CASCADE,
  CONSTRAINT `evaluation_evaluator_scores_ibfk_2` FOREIGN KEY (`criteria_id`) REFERENCES `evaluation_criteria` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

