-- 
-- Table structure for table `evaluation_evaluator_status`
-- 

DROP TABLE IF EXISTS `evaluation_evaluator_status`;
CREATE TABLE `evaluation_evaluator_status` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `evaluation_instance_id` int(11) NOT NULL,
  `evaluator_id` int(11) NOT NULL,
  `status` enum('pending','completed') NOT NULL DEFAULT 'pending',
  `total_score` decimal(5,2) DEFAULT 0.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ev_status` (`evaluation_instance_id`,`evaluator_id`),
  KEY `evaluator_id` (`evaluator_id`),
